fn put(out:*mut u8,i:usize,x:i32){let b=x.to_le_bytes();unsafe{for k in 0..4{*out.add(i*4+k)=b[k]}}}
#[no_mangle]
pub unsafe extern "C" fn non_preemptive_priority_scheduling(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<4||*v<1||*v>10||n!=1+3*(*v as usize){return -1}let count=*v as usize;let mut a=[0i32;10];let mut b=[0i32;10];let mut p=[0i32;10];let mut done=[false;10];for i in 0..count{let av=*v.add(1+3*i);let bv=*v.add(2+3*i);let pv=*v.add(3+3*i);if !(0..=20).contains(&av)||!(1..=10).contains(&bv)||!(0..=10).contains(&pv){return -1}for j in 0..i{if p[j]==pv as i32{return -1}}a[i]=av as i32;b[i]=bv as i32;p[i]=pv as i32}if out.is_null()||cap<count*4{return -2}let mut now=0;let mut z=0;while z<count{let mut pick:Option<usize>=None;for i in 0..count{if !done[i]&&a[i]<=now&&pick.map_or(true,|j|p[i]<p[j]||(p[i]==p[j]&&a[i]<a[j])){pick=Some(i)}}let i=match pick{Some(i)=>i,None=>{now=(0..count).filter(|&i|!done[i]).map(|i|a[i]).min().unwrap();continue}};done[i]=true;put(out,z,i as i32);now+=b[i];z+=1}(count*4)as i64}
